import json
import os
import re
import urllib.error
import urllib.request
from urllib.parse import urlparse

from lfx.custom.custom_component.component import Component
from lfx.io import IntInput, MessageTextInput, Output, StrInput
from lfx.schema.message import Message

DISCLAIMER = (
    "Hasil ini adalah decision support (prototype dengan data sintetis). "
    "Setiap kandidat discrepancy wajib diverifikasi farmasis; keputusan klinis akhir ada di tangan farmasis."
)

UUID_RE = re.compile(r"\b[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\b")
LABELED_RE = re.compile(r"patient[_\s-]*id\s*[:=]\s*([A-Za-z0-9][A-Za-z0-9_-]*)", re.IGNORECASE)
SHORT_RE = re.compile(r"\bP\d+\b", re.IGNORECASE)


def _to_text(value) -> str:
    if value is None:
        return ""
    text = getattr(value, "text", None)
    if isinstance(text, str):
        return text
    return str(value)


class PrioMedAnalyzeClient(Component):
    display_name = "PrioMed-Rec Analyze Client"
    description = (
        "Extracts patient_id from the pharmacist query and calls POST /analyze on the PrioMed-Rec API. "
        "Returns a structured JSON envelope; never raises, so downstream nodes always receive a result."
    )
    documentation: str = ""
    icon = "Globe"
    name = "PrioMedAnalyzeClient"

    inputs = [
        MessageTextInput(
            name="query",
            display_name="Pharmacist Query",
            info="Pharmacist message that contains a patient ID (e.g. P001, patient_id: P001, or a UUID).",
            required=True,
        ),
        StrInput(
            name="api_base_url",
            display_name="API Base URL",
            info="Base URL of the PrioMed-Rec FastAPI backend. If empty, env PRIOMEDREC_API_URL or http://localhost:8000 is used.",
            value="http://localhost:8000",
        ),
        StrInput(
            name="endpoint_path",
            display_name="Endpoint Path",
            info="Path of the patient-level analysis endpoint (POST, JSON body {patient_id}).",
            value="/analyze",
            advanced=True,
        ),
        IntInput(
            name="timeout",
            display_name="Timeout (seconds)",
            info="HTTP timeout for the API call.",
            value=60,
            advanced=True,
        ),
    ]

    outputs = [
        Output(display_name="Analysis Result", name="analysis", method="analyze_patient"),
    ]

    def _extract_patient_id(self, text: str):
        match = UUID_RE.search(text)
        if match:
            return match.group(0)
        match = LABELED_RE.search(text)
        if match:
            return match.group(1)
        match = SHORT_RE.search(text)
        if match:
            return match.group(0).upper()
        return None

    def _envelope(self, payload: dict) -> Message:
        text = json.dumps(payload, ensure_ascii=False, indent=2)
        self.status = text
        return Message(text=text)

    def analyze_patient(self) -> Message:
        query = _to_text(self.query).strip()
        patient_id = self._extract_patient_id(query)
        if not patient_id:
            return self._envelope(
                {
                    "status": "NEEDS_PATIENT_ID",
                    "message": "Tidak ditemukan patient_id pada pesan farmasis (contoh: P001). Analisis tidak dijalankan.",
                    "disclaimer": DISCLAIMER,
                }
            )

        base = (_to_text(self.api_base_url).strip() or os.environ.get("PRIOMEDREC_API_URL", "").strip() or "http://localhost:8000")
        path = _to_text(self.endpoint_path).strip() or "/analyze"
        url = base.rstrip("/") + "/" + path.lstrip("/")
        if urlparse(url).scheme not in ("http", "https"):
            return self._envelope(
                {
                    "status": "ERROR",
                    "error_type": "INVALID_URL",
                    "message": "API Base URL harus diawali http:// atau https://",
                    "patient_id": patient_id,
                    "disclaimer": DISCLAIMER,
                }
            )

        try:
            timeout = int(self.timeout) if self.timeout else 60
        except (TypeError, ValueError):
            timeout = 60

        body = json.dumps({"patient_id": patient_id}).encode("utf-8")
        request = urllib.request.Request(
            url,
            data=body,
            headers={"Content-Type": "application/json", "Accept": "application/json"},
            method="POST",
        )
        try:
            with urllib.request.urlopen(request, timeout=timeout) as response:  # noqa: S310 (scheme validated above)
                raw = response.read().decode("utf-8", errors="replace")
                http_status = response.status
        except urllib.error.HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="replace")[:1000]
            return self._envelope(
                {
                    "status": "ERROR",
                    "error_type": "HTTP_ERROR",
                    "http_status": exc.code,
                    "message": "API PrioMed-Rec mengembalikan error. Analisis tidak tersedia.",
                    "api_detail": detail,
                    "patient_id": patient_id,
                    "endpoint": url,
                    "disclaimer": DISCLAIMER,
                }
            )
        except Exception as exc:  # noqa: BLE001 - connection refused, timeout, DNS, etc.
            return self._envelope(
                {
                    "status": "ERROR",
                    "error_type": "CONNECTION_ERROR",
                    "message": "Tidak dapat menghubungi API PrioMed-Rec. Pastikan FastAPI berjalan dan URL benar. Analisis tidak tersedia.",
                    "api_detail": str(exc)[:500],
                    "patient_id": patient_id,
                    "endpoint": url,
                    "disclaimer": DISCLAIMER,
                }
            )

        try:
            parsed = json.loads(raw)
        except json.JSONDecodeError:
            return self._envelope(
                {
                    "status": "ERROR",
                    "error_type": "INVALID_JSON_RESPONSE",
                    "message": "Respons API bukan JSON valid. Analisis tidak tersedia.",
                    "api_detail": raw[:500],
                    "patient_id": patient_id,
                    "endpoint": url,
                    "disclaimer": DISCLAIMER,
                }
            )

        return self._envelope(
            {
                "status": "OK",
                "patient_id": patient_id,
                "endpoint": url,
                "http_status": http_status,
                "api_response": parsed,
                "disclaimer": DISCLAIMER,
            }
        )
